#!/bin/sh
# Build only the selected stock Wine LSC PE/Unix halves and the Steam PE shim.
# All Wine/Valve sources, tools generated by Wine, and output stay in build dirs.
# No installed runtime, Steam client, CrossOver tree, or prefix is modified.
set -eu

here=$(cd "$(dirname "$0")" && pwd)
repo=$(cd "$here/../.." && pwd)
wine_version=11.17
proton_commit=164e0ccd2ea2b1ec2e5d08dc97f65b184c2539ca
proton_digest=b286df1df46a70d9e2cc674676afcc6e08b1a56ce472e5add0932b86940657bf
toolchain=""
bison=""
runtime=""
work=""
source=""
build=""
output=""
jobs=2

usage() {
    cat <<'EOF'
Build the LSC bridge and Steam shim against pinned stock Wine Devel 11.17, 11.18 or 11.19.

Required:
  --toolchain DIR     Existing LLVM MinGW root, containing bin/
  --bison FILE        Existing bison 3.0+ executable (no dependency installation)
  --runtime-root DIR  Matching stock Wine Devel root, containing bin/ and lib/wine/
  --work DIR          Private source/cache/build workspace

Optional:
  --source DIR        Reuse a source checkout at the exact pinned Wine commit
  --wine-version VER  Exact supported Devel version: 11.17 (default), 11.18 or 11.19
  --build DIR         Reuse a matching x86_64 Wine configured build tree
  --output DIR        Stage LSC/shim here (default: WORK/bridge)
  --jobs N            PE make parallelism, 1-16 (default: 2)
  --help              Show this help without building or downloading anything

Environment:
  NP_WINE_SDKROOT     Existing absolute macOS SDK directory (default: xcrun SDK)

This builds only LSC/shim and their required headers, tools, and PE import/runtime
libraries. It never builds or replaces Wine's Unix ntdll. The installed ntdll.so
is copied into the build directory only as the matching link input.
Forwarders are built separately with bridge/wine-native/build.sh.
EOF
}

fail() { echo "$*" >&2; exit 1; }
while [ "$#" -gt 0 ]; do
    case "$1" in
        --help) usage; exit 0 ;;
        --toolchain|--bison|--runtime-root|--work|--source|--build|--output|--jobs|--wine-version)
            [ "$#" -ge 2 ] || fail "Missing value for $1"
            case "$1" in
                --toolchain) toolchain=$2 ;;
                --bison) bison=$2 ;;
                --runtime-root) runtime=$2 ;;
                --work) work=$2 ;;
                --source) source=$2 ;;
                --build) build=$2 ;;
                --output) output=$2 ;;
                --jobs) jobs=$2 ;;
                --wine-version) wine_version=$2 ;;
            esac
            shift 2 ;;
        *) fail "Unknown argument: $1" ;;
    esac
done
case "$wine_version" in
    11.17) wine_commit=36b6a2cf679fb395f668a917b76537190e212d9c ;;
    11.18) wine_commit=7b3fff76fa5178f6ce0141b2c776afa2a822f101 ;;
    11.19) wine_commit=455e3509b98a6919fd4ad1def4803e08c41c03b2 ;;
    *) fail "Unsupported --wine-version: use Devel 11.17, 11.18 or 11.19 (not Staging)." ;;
esac
wine_tag="wine-$wine_version"
[ -n "$toolchain" ] && [ -n "$bison" ] && [ -n "$runtime" ] && [ -n "$work" ] || {
    usage >&2
    fail "Missing required options."
}
case "$jobs" in ''|*[!0-9]*) fail "--jobs must be an integer from 1 to 16" ;; esac
[ "$jobs" -ge 1 ] && [ "$jobs" -le 16 ] || fail "--jobs must be from 1 to 16"
[ "$(uname -s)" = Darwin ] || fail "The Unix bridge requires macOS."
for tool in git make flex rsync python3 xcrun lipo nm otool install_name_tool codesign; do
    command -v "$tool" >/dev/null 2>&1 || fail "Missing required tool: $tool"
done
[ -d "$toolchain/bin" ] || fail "--toolchain must contain bin/"
toolchain=$(cd "$toolchain" && pwd -P)
for tool in x86_64-w64-mingw32-gcc x86_64-w64-mingw32-g++ i686-w64-mingw32-gcc i686-w64-mingw32-g++; do
    [ -x "$toolchain/bin/$tool" ] || fail "Missing toolchain executable: $tool"
done
[ -x "$bison" ] || fail "--bison must name an executable"
bison_dir=$(cd "$(dirname "$bison")" && pwd -P)
bison_name=$(basename "$bison")
case "$bison_name" in *[!A-Za-z0-9_.-]*) fail "Unsupported bison executable filename" ;; esac
bison="$bison_dir/$bison_name"
"$bison" --version | head -1
printf '%%define parse.error verbose\n%%%%\nempty: ;\n' |
    "$bison" -o /dev/null /dev/stdin >/dev/null 2>&1 || fail "Bison 3.0 or newer is required."
[ -d "$runtime" ] || fail "Wine runtime root does not exist"
runtime=$(cd "$runtime" && pwd -P)
ntdll="$runtime/lib/wine/x86_64-unix/ntdll.so"
[ -f "$ntdll" ] || fail "Runtime is missing stock x86_64-unix/ntdll.so"
loader="$runtime/bin/wine"
[ -x "$loader" ] || loader="$runtime/bin/wine64"
[ -x "$loader" ] || fail "Runtime has no executable bin/wine or bin/wine64"
version=$(env -u DYLD_INSERT_LIBRARIES -u STEAM_DYLD_INSERT_LIBRARIES "$loader" --version)
[ "$version" = "$wine_tag" ] || fail "Runtime reports '$version'; expected $wine_tag"
[ "$(lipo -archs "$ntdll")" = x86_64 ] || fail "Runtime ntdll.so must be x86_64"

canonical() { python3 -c 'import os, sys; print(os.path.realpath(sys.argv[1]))' "$1"; }
work=$(canonical "$work")
source=${source:-$work/source}
build=${build:-$work/build}
output=${output:-$work/bridge}
source=$(canonical "$source")
build=$(canonical "$build")
output=$(canonical "$output")
# Wine's generated make rules do not safely represent source/build whitespace.
# This restriction does not apply to the installed runtime or output paths.
case "$source$build" in *[[:space:]]*) fail "Wine source/build paths must not contain whitespace" ;; esac
for path in "$work" "$source" "$build" "$output"; do
    case "$path/" in "$runtime/"*) fail "Build paths must be outside the installed runtime" ;; esac
    case "$path/" in /Applications/*) fail "Build paths must be outside /Applications" ;; esac
done
if [ -d "$source/.git" ]; then
    [ "$(git -C "$source" rev-parse HEAD)" = "$wine_commit" ] || fail "Wine source is not pinned commit $wine_commit"
else
    [ ! -e "$source" ] || fail "Existing source directory is not a Git checkout"
fi
if [ -f "$build/Makefile" ]; then
    LC_ALL=C grep -q '^host_cpu = x86_64$' "$build/config.status" || fail "Existing build host is not x86_64"
    LC_ALL=C grep -Fqx "#define PACKAGE_VERSION \"$wine_version\"" "$build/include/config.h" || fail "Existing build is not Wine $wine_version"
    configured_source=$(sed -n 's/^srcdir = //p' "$build/Makefile" | head -1)
    [ -n "$configured_source" ] || fail "Existing Makefile does not record srcdir"
    [ "$(cd "$build" && cd "$configured_source" && pwd -P)" = "$source" ] || fail "Existing build points to another source tree"
fi
if [ "${NP_WINE_SDKROOT+x}" = x ]; then
    SDKROOT=$NP_WINE_SDKROOT
else
    SDKROOT=$(xcrun --sdk macosx --show-sdk-path)
fi
SDKROOT=$(python3 - "$SDKROOT" <<'PY'
from pathlib import Path
import sys

path = sys.argv[1]
if not path.startswith("/") or any(ord(c) < 32 or ord(c) == 127 for c in path) or not Path(path).is_dir():
    raise SystemExit("macOS SDK root must be an existing absolute directory (NP_WINE_SDKROOT or xcrun).")
print(Path(path).resolve())
PY
)
export SDKROOT
mkdir -p "$work" "$(dirname "$source")" "$build" "$output"

if [ ! -d "$source/.git" ]; then
    git clone --depth 1 --branch "$wine_tag" https://github.com/wine-mirror/wine.git "$source"
fi
[ "$(git -C "$source" rev-parse HEAD)" = "$wine_commit" ] || fail "Wine source is not pinned commit $wine_commit"
if ! LC_ALL=C grep -q 'WINE_CONFIG_MAKEFILE(dlls/lsteamclient)' "$source/configure.ac"; then
    git -C "$source" apply "$repo/bridge/register-components.diff"
fi
LC_ALL=C grep -q 'WINE_CONFIG_MAKEFILE(programs/steam.exe)' "$source/configure.ac" || fail "Wine Steam shim component is not registered"

PROTON_COMMIT="$proton_commit" BASELINE_DIGEST="$proton_digest" \
    WORK="$work/proton-lsc" TREE="$work/lsteamclient" sh "$repo/lsteamclient/fetch.sh"
mkdir -p "$source/dlls/lsteamclient" "$source/programs/steam.exe"
rsync -a --delete "$work/lsteamclient/" "$source/dlls/lsteamclient/"
rsync -a --exclude build.sh --exclude fetch-headers.sh "$repo/steam-shim/" "$source/programs/steam.exe/"
OPENVR_COMMIT=f51d87ecf8f7903e859b0aa4d617ff1e5f33db5a \
    WINE_COMMIT=015230dc0f78a543032dea0907f6c97304b25ca3 \
    CACHE="$work/proton-headers-cache" OUT="$source/programs/steam.exe/proton-headers" \
    LSC_TREE="$work/lsteamclient" sh "$repo/steam-shim/fetch-headers.sh"

PATH="$bison_dir:$toolchain/bin:$PATH"
export PATH
cd "$build"
if [ -f Makefile ]; then
    ./config.status Makefile
else
    BISON="$bison_name" "$source/configure" \
        --enable-archs=i386,x86_64 --disable-tests --without-freetype --without-x \
        --host=x86_64-apple-darwin CC='/usr/bin/clang -arch x86_64' \
        CXX='/usr/bin/clang++ -arch x86_64'
fi
LC_ALL=C grep -q '^host_cpu = x86_64$' config.status || fail "Configure did not select x86_64"
mkdir -p dlls/ntdll
cp "$ntdll" dlls/ntdll/ntdll.so
make -j"$jobs" dlls/lsteamclient/x86_64-windows/lsteamclient.dll \
    dlls/lsteamclient/i386-windows/lsteamclient.dll programs/steam.exe/x86_64-windows/steam.exe

module=dlls/lsteamclient
cpps=$(sed -n 's/^[[:space:]]*\([A-Za-z0-9_]*\.cpp\)[[:space:]]*\\*[[:space:]]*$/\1/p' "$source/$module/Makefile.in")
[ -n "$cpps" ] || fail "No Unix bridge sources found"
set --
# This list contains only validated, whitespace-free filenames from pinned SOURCES.
# shellcheck disable=SC2086
for cpp in $cpps; do
    object="$module/${cpp%.cpp}.o"
    /usr/bin/clang++ -arch x86_64 -isysroot "$SDKROOT" -mmacosx-version-min=15.0 \
        -Werror=unguarded-availability-new -I"$module" -I"$source/$module" \
        -Iinclude -I"$source/include" -D__WINESRC__ -DSTEAM_API_EXPORTS \
        -Dprivate=public -Dprotected=public -DWINE_UNIX_LIB \
        -fPIC -fasynchronous-unwind-tables -g -O2 -c -o "$object" "$source/$module/$cpp"
    set -- "$@" "$object"
done
/usr/bin/clang++ -arch x86_64 -isysroot "$SDKROOT" -mmacosx-version-min=15.0 -dynamiclib \
    -install_name @rpath/lsteamclient.so -Wl,-rpath,@loader_path/ \
    -o "$module/lsteamclient.so" "$@" dlls/ntdll/ntdll.so -lc++ -Wl,-undefined,dynamic_lookup
install_name_tool -change ntdll.so @rpath/ntdll.so "$module/lsteamclient.so"
[ "$(lipo -archs "$module/lsteamclient.so")" = x86_64 ] || fail "Unix bridge is not x86_64"
[ "$(stat -f %z "$module/lsteamclient.so")" -gt 1000000 ] || fail "Unix bridge is too small; the link may have dropped objects"
signing=$(codesign -dv "$module/lsteamclient.so" 2>&1 || true)
printf '%s\n' "$signing" | LC_ALL=C grep -q 'not signed at all' || fail "Unix bridge must be unsigned"
LC_ALL=C grep -aq 'ole32\.dll' programs/steam.exe/x86_64-windows/steam.exe && fail "Steam shim unexpectedly imports ole32"

for arch in x86_64 i386; do
    file="$module/$arch-windows/lsteamclient.dll"
    [ "$(stat -f %z "$file")" -gt 1000000 ] || fail "PE LSC bridge is too small: $file"
    info=$(python3 "$repo/bridge/pe-info.py" "$file")
    case "$info" in "$arch "*) ;; *) fail "PE bridge architecture mismatch: $info" ;; esac
    echo "LSC $info"
    mkdir -p "$output/$arch-windows"
    cp "$file" "$output/$arch-windows/lsteamclient.dll"
done
info=$(python3 "$repo/bridge/pe-info.py" programs/steam.exe/x86_64-windows/steam.exe)
[ "$(stat -f %z programs/steam.exe/x86_64-windows/steam.exe)" -gt 1000000 ] || fail "Steam shim is too small"
case "$info" in 'x86_64 '*) ;; *) fail "Steam shim architecture mismatch: $info" ;; esac
echo "Steam shim $info"
mkdir -p "$output/x86_64-unix"
cp "$module/lsteamclient.so" "$output/x86_64-unix/lsteamclient.so"
cp programs/steam.exe/x86_64-windows/steam.exe "$output/x86_64-windows/steam.exe"
python3 - "$output" "$ntdll" "$wine_commit" "$proton_commit" "$build/dlls/ntdll/ntdll.so" "$wine_version" "$SDKROOT" <<'PY'
import hashlib
import json
import pathlib
import subprocess
import sys

output, ntdll = map(pathlib.Path, sys.argv[1:3])
sha = lambda path: hashlib.sha256(path.read_bytes()).hexdigest()
if sha(ntdll) != sha(pathlib.Path(sys.argv[5])):
    raise SystemExit("Runtime ntdll changed after its build link copy was created.")
stock_symbols = subprocess.check_output(["nm", "-gU", str(ntdll)], text=True).splitlines()
refs = subprocess.check_output(["nm", "-u", str(output / "x86_64-unix/lsteamclient.so")], text=True).splitlines()
refs = [s.strip() for s in refs if s.startswith(("_Nt", "_ntdll_", "___wine_dbg"))]
missing = [s for s in refs if not any(line.endswith(" " + s) for line in stock_symbols)]
if missing:
    raise SystemExit("Runtime Wine symbols missing: " + ", ".join(missing))
files = ["x86_64-windows/lsteamclient.dll", "i386-windows/lsteamclient.dll",
         "x86_64-unix/lsteamclient.so", "x86_64-windows/steam.exe"]
provenance = {"schemaVersion": 1, "wineVersion": sys.argv[6], "wineCommit": sys.argv[3],
              "protonCommit": sys.argv[4], "runtimeNtdllSHA256": sha(ntdll),
              "macosSDKRoot": sys.argv[7],
              "files": {f: sha(output / f) for f in files},
              "ntdllRebuilt": False, "runtimeModified": False,
              "validation": "PE architectures, unsigned x86_64 Unix bridge, matching Wine symbol exports. No Steam session validation."}
(output / "lsteamclient-provenance.json").write_text(json.dumps(provenance, indent=2) + "\n")
print("Verified", len(refs), "Wine symbol references against the supplied runtime.")
PY
echo "Built LSC/shim in $output; Steamworks headers: $work/lsteamclient/steamworks_sdk_165"
echo "Build forwarders separately before creating a native Steam bridge manifest."
